/**
 * The shared NB2 vectors (native-bridge-plugins protocol/vectors/nb2, generated by bft-core nb2ref, NB2-03 #1099), replayed against
 * the plug-in byte for byte: Γ, the verifier (positive and negative), seal receipts, gap proofs, chain folds, segment logs, the vault
 * model, the wallet refusals and the primitives. The file is imported by its digest.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { test } from 'node:test';

import { toHex } from '../../src/bytes.js';
import { u256 } from '../../src/nb2/cbor.js';
import { ALL_RULES, Nb2Error, WalletError, type Rule } from '../../src/nb2/errors.js';
import { ConfigError, buildParams, construct, decodeConfig, domainOf, type Build } from '../../src/nb2/config.js';
import { revertData, selectorOf, signatureOf, SELECTOR } from '../../src/nb2/abi.js';
import { TAG_ARCHIVE_GENESIS, TAG_ARCHIVE_STEP, TAG_DEPOSIT_SECRET, TOPIC } from '../../src/nb2/deposit.js';
import { ASSET_UCT } from '../../src/nb2/config.js';
import { minterScalarValid, verifyUnlockDigest } from '../../src/nb2/crypto.js';
import { burnIndex, capacityExceeded, capacityPreflight, checkCompanion, checkStateRead, maxProofs, verifySealReceipt } from '../../src/nb2/rules.js';
import { checkSegmentLog, foldHistory, gapProofLen, gapRoot } from '../../src/nb2/segment.js';
import { TrustInput } from '../../src/nb2/trust.js';
import { VaultModel, type VaultEvent, type RecipientBehaviour } from '../../src/nb2/vaultmodel.js';
import { verdictAbi, verifyReturn } from '../../src/nb2/verify.js';
import { depositedData } from '../../src/nb2/deposit.js';
import { segmentSealedData } from '../../src/nb2/segment.js';

const DIR = new URL('../../../../protocol/vectors/nb2/', import.meta.url);
const text = readFileSync(new URL('nb2-vectors.json', DIR), 'utf8');

/** JSON with every integer as a bigint (uint64 fields exceed 2^53). */
const F = JSON.parse(text, function (this: unknown, _k: string, v: unknown, ctx?: { source?: string }) {
  if (typeof v === 'number' && Number.isInteger(v) && ctx?.source !== undefined && /^-?\d+$/.test(ctx.source)) return BigInt(ctx.source);
  return v;
}) as any;

const hx = (s: string | undefined | null): Uint8Array => (s ? Uint8Array.from(Buffer.from(s.slice(2), 'hex')) : new Uint8Array());
const h0x = (b: Uint8Array): string => `0x${toHex(b)}`;

interface Expect { error?: string; args?: string[]; onChainError?: string; revert?: string }

/** The vectors' rendering of an outcome (bft-core nb2ref `expectOf`). */
function expectOf(e: unknown): Expect {
  if (e === null) return {};
  if (e instanceof WalletError) return { error: e.reason };
  if (!(e instanceof Nb2Error)) return { error: `?${String((e as Error)?.message ?? e)}` };
  const out: Expect = { error: e.rule };
  if (e.args?.length) {
    out.args = e.args;
    const vals = e.args.map((a) => (a.startsWith('0x') ? hx(a) : BigInt(a)));
    out.revert = h0x(revertData(e.rule, ...vals));
    return out;
  }
  let on: Rule = e.rule;
  if (e.rule === 'SealEpoch' || e.rule === 'NoEntryForEpoch') {
    on = 'QuorumNotMet';
    for (let x: Nb2Error | undefined = e; x; x = x.inner) if (x.rule === 'DepositUC') on = 'DepositUC';
    out.onChainError = on;
  }
  // a seal receipt wrapping the retryable NoEntryForEpoch: the same EVM UC is DepositUC on chain
  if (e.rule === 'SealReceipt') for (let x: Nb2Error | undefined = e.inner; x; x = x.inner) if (x.rule === 'NoEntryForEpoch') out.onChainError = 'DepositUC';
  if (!['SealReceipt', 'SegmentLog', 'CapacityPreflight', 'CapacityExceeded', 'ImplausibleIndex', 'EvidencePruned'].includes(on)) out.revert = h0x(revertData(on));
  return out;
}

const norm = (x: Expect | undefined): string => JSON.stringify({ error: x?.error ?? '', args: x?.args ?? [], onChain: x?.onChainError ?? '', revert: x?.revert ?? '' });

async function outcome<T>(f: () => Promise<T> | T): Promise<[T | null, unknown]> {
  try {
    return [await f(), null];
  } catch (e) {
    return [null, e];
  }
}

const deployments = new Map<string, { trust: TrustInput; gamma: Uint8Array; build: Build; dep: any }>();
async function dep(name: string): Promise<{ trust: TrustInput; gamma: Uint8Array; build: Build; dep: any }> {
  let d = deployments.get(name);
  if (!d) {
    const v = F.deployments[name];
    d = { trust: await TrustInput.fromBundle(hx(v.trustBundle), hx(v.trustGenesisEntryId)), gamma: hx(v.gamma), build: v.build, dep: v };
    deployments.set(name, d);
  }
  return d;
}

test('vector file digest', () => {
  const want = readFileSync(new URL('nb2-vectors.json.sha256', DIR), 'utf8').trim().split(/\s+/)[0];
  assert.equal(createHash('sha256').update(text).digest('hex'), want);
  assert.equal(F.nativeBridgeProtocolVersion, 9n);
});

test('rules, signatures and selectors', () => {
  assert.deepEqual(F.rules.map((r: any) => r.name), [...ALL_RULES]);
  for (const r of F.rules) {
    assert.equal(signatureOf(r.name), r.signature, r.name);
    assert.equal(h0x(selectorOf(r.name)), r.selector, r.name);
  }
});

test('primitives', () => {
  const c = F.primitives.constants;
  assert.equal(h0x(TAG_DEPOSIT_SECRET), c.DEPOSIT_SECRET);
  assert.equal(h0x(TAG_ARCHIVE_GENESIS), c.ARCHIVE_GENESIS);
  assert.equal(h0x(TAG_ARCHIVE_STEP), c.ARCHIVE_STEP);
  assert.equal(h0x(ASSET_UCT), c.asset);
  for (const k of ['deposit', 'redeem', 'domain', 'config', 'state', 'verifyReturn'] as const) assert.equal(h0x(SELECTOR[k]), c[`selector.${k}`], k);
  for (const k of ['Deposited', 'Paid', 'SegmentSealed'] as const) assert.equal(h0x(TOPIC[k]), c[`topic0.${k}`], k);
  for (const v of F.primitives.minterScalars) assert.equal(minterScalarValid(hx(v.scalar)), v.valid, v.scalar);
  assert.ok(F.primitives.unlockRecovery.length >= 9);
  for (const v of F.primitives.unlockRecovery) {
    let e: unknown = null;
    try {
      verifyUnlockDigest(hx(v.key), hx(v.digest), hx(v.unlock));
    } catch (x) {
      e = x;
    }
    assert.equal(norm(expectOf(e)), norm(v.expect), v.id);
  }
});

test('deployments decode under their build', async () => {
  for (const [name, v] of Object.entries<any>(F.deployments)) {
    const cfg = decodeConfig(hx(v.gamma), buildParams(v.build));
    assert.equal(h0x(domainOf(hx(v.gamma))), v.domain, name);
    assert.equal(cfg.K, v.K);
    assert.equal(cfg.B, v.B);
    await dep(name);
  }
});

test('config: ConfigShape and BadConfig(field)', () => {
  for (const v of F.config) {
    const p = buildParams(F.deployments[v.deployment].build);
    const gamma = hx(v.gamma);
    let ve: unknown = null;
    try {
      decodeConfig(gamma, p);
    } catch (e) {
      ve = e;
    }
    let ce: unknown = null;
    try {
      construct(gamma, { address: hx(v.address), chainId: v.chainId, verifierCodeHash: hx(v.verifierCodeHash) }, p);
    } catch (e) {
      ce = e;
    }
    if (ve instanceof ConfigError) ve = new Nb2Error('ConfigShape');
    assert.equal(norm(expectOf(ve)), norm(v.verifier), `${v.id} verifier: ${String(ve)}`);
    assert.equal(norm(expectOf(ce)), norm(v.constructor), `${v.id} constructor: ${String(ce)}`);
  }
});

test('verifier: verifyReturn on every token vector', async () => {
  const failures: string[] = [];
  for (const v of F.verifier) {
    const d = await dep(v.deployment);
    const gamma = v.gamma ? hx(v.gamma) : d.gamma;
    let [vd, e] = await outcome(() => verifyReturn(gamma, hx(v.evidence), d.trust, buildParams(d.build)));
    if (e instanceof ConfigError) e = new Nb2Error('ConfigShape');
    if (norm(expectOf(e)) !== norm(v.expect)) {
      failures.push(`${v.id}: got ${norm(expectOf(e))} (${String((e as Error)?.message ?? '')}), want ${norm(v.expect)}`);
      continue;
    }
    if (vd !== null && h0x(verdictAbi(vd)) !== v.verdict.abi) failures.push(`${v.id}: verdict differs`);
  }
  assert.deepEqual(failures, []);
});

test('seal receipts: SealReceipt and the burn index', async () => {
  const failures: string[] = [];
  for (const v of F.sealReceipts) {
    const d = await dep(v.deployment);
    const cfg = decodeConfig(d.gamma, buildParams(d.build));
    const domain = domainOf(d.gamma);
    const resultOf = (sr: Awaited<ReturnType<typeof verifySealReceipt>> | null): any => {
      const { a, startHead } = burnIndex(cfg, domain, sr);
      const out: any = sr === null ? { segment: 0n } : {
        segment: sr.segment.index, headBefore: h0x(sr.segment.before), headAfter: h0x(sr.segment.after),
      };
      out.ids = sr === null ? [] : sr.segment.z.map(h0x);
      if (sr !== null) out.root = h0x(sr.segment.root);
      out.burnIndex = a;
      out.startHead = h0x(startHead);
      return out;
    };
    const cmpResult = (got: any, want: any): boolean =>
      JSON.stringify(got, (_k, x) => (typeof x === 'bigint' ? x.toString() : x)) === JSON.stringify(want, (_k, x) => (typeof x === 'bigint' ? x.toString() : x));
    if (v.noReceipt) {
      if (!cmpResult(resultOf(null), v.result)) failures.push(`${v.id}: burn index without a receipt`);
      continue;
    }
    const [sr, e] = await outcome(() => verifySealReceipt(cfg, domain, d.trust, hx(v.receipt)));
    if (norm(expectOf(e)) !== norm(v.expect) || (e instanceof Nb2Error && e.inner?.rule !== v.innerRule)) {
      failures.push(`${v.id}: got ${norm(expectOf(e))} inner ${(e as Nb2Error)?.inner?.rule} (${String((e as Error)?.message ?? '')}), want ${norm(v.expect)} inner ${v.innerRule}`);
      continue;
    }
    if (sr !== null && !cmpResult(resultOf(sr), v.result)) failures.push(`${v.id}: positive result differs`);
  }
  assert.deepEqual(failures, []);
});

test('gap proofs', () => {
  for (const v of F.gapProofs) {
    const m = gapRoot(v.K, hx(v.eta), hx(v.proof));
    assert.equal(m !== null && h0x(m) === v.root, !v.expect.error, v.id);
  }
});

test('chain folds: BadGapProof(position) and ChainMismatch', async () => {
  for (const v of F.chainFolds) {
    const hist = hx(v.history);
    const pl = gapProofLen(v.K);
    const proofs: Uint8Array[] = [];
    for (let i = 32; i + pl <= hist.length; i += pl) proofs.push(hist.subarray(i, i + pl));
    const [x, e0] = await outcome(() => foldHistory(hx(v.domain), v.K, hx(v.eta), v.a, hist.subarray(0, 32), proofs));
    const e = e0 ?? (x !== null && h0x(x) !== v.storedHead ? new Nb2Error('ChainMismatch') : null);
    assert.equal(norm(expectOf(e)), norm(v.expect), v.id);
  }
});

test('segment logs', async () => {
  for (const v of F.segmentLogs) {
    const [s, e] = await outcome(() => checkSegmentLog(hx(v.domain), v.K, v.segment, hx(v.expectedHeadBefore), hx(v.data)));
    assert.equal(norm(expectOf(e)), norm(v.expect), v.id);
    if (s !== null) {
      assert.equal(h0x(s.root), v.root, v.id);
      assert.equal(h0x(s.after), v.headAfter, v.id);
    }
  }
});

function eventJson(d: Uint8Array, e: VaultEvent): any {
  switch (e.name) {
    case 'Deposited': return { name: e.name, topics: [h0x(TOPIC.Deposited), h0x(u256(e.n))], data: h0x(depositedData(d, e.amount, e.rho, e.firstOwner)) };
    case 'Paid': {
      const r = new Uint8Array(32);
      r.set(e.recipient, 12);
      return { name: e.name, topics: [h0x(TOPIC.Paid), h0x(e.eta), h0x(r)], data: h0x(u256(e.amount)) };
    }
    default: return { name: e.name, topics: [h0x(TOPIC.SegmentSealed), h0x(u256(e.segment))], data: h0x(segmentSealedData(e.before, e.after, e.ids)) };
  }
}

function stateJson(v: VaultModel): string {
  const s = v.state();
  const { current, previous } = v.liveIds();
  return JSON.stringify({
    deposits: String(s.deposits), segment: String(s.segment), population: String(s.population), outstanding: String(s.outstanding),
    head: h0x(s.head), previousHead: h0x(s.previousHead), current: current.map(h0x), previous: previous.map(h0x),
    accounting: h0x(u256(v.A)), tagWords: v.T.map((ws) => ws.map((w) => h0x(u256(w)))),
  });
}
const wantState = (s: any): string => JSON.stringify({
  deposits: String(s.deposits), segment: String(s.segment), population: String(s.population), outstanding: String(s.outstanding), head: s.head,
  previousHead: s.previousHead, current: s.current, previous: s.previous, accounting: s.accounting, tagWords: s.tagWords,
});

test('vault model: every vault vector, step by step', () => {
  const failures: string[] = [];
  for (const v of F.vault) {
    const d = F.deployments[v.deployment];
    const vt = new VaultModel(hx(d.gamma), { address: hx(d.vault), chainId: d.chainId, verifierCodeHash: hx(d.verifierCodeHash) }, buildParams(d.build));
    if (v.harnessState) {
      const h = v.harnessState;
      vt.setState(h.deposits, h.segment, h.population, BigInt(h.outstanding), hx(h.head), hx(h.previousHead), h.current.map(hx), h.previous.map(hx));
    }
    v.steps.forEach((st: any, i: number) => {
      const before = vt.events.length;
      let err: unknown = null;
      let inner: Nb2Error | null = null;
      try {
        if (st.op === 'deposit') vt.deposit(BigInt(st.value), hx(st.firstOwner), hx(st.rho));
        else {
          const ver = st.verifierRevert !== undefined ? { revert: hx(st.verifierRevert) } : { ret: hx(st.verifierReturn) };
          inner = vt.redeem(hx(st.claimedEta), st.claimedStart, hx(st.history), ver, (st.recipient || 'accepts') as RecipientBehaviour).inner;
        }
      } catch (e) {
        err = e;
      }
      if (norm(expectOf(err)) !== norm(st.expect) || (inner?.rule ?? undefined) !== st.innerError) {
        failures.push(`${v.id} step ${i}: got ${norm(expectOf(err))} inner ${inner?.rule}, want ${norm(st.expect)} inner ${st.innerError}`);
        return;
      }
      const evs = vt.events.slice(before).map((e) => eventJson(vt.d, e));
      if (JSON.stringify(evs) !== JSON.stringify(st.events ?? [])) failures.push(`${v.id} step ${i}: events differ`);
      if (stateJson(vt) !== wantState(st.state)) failures.push(`${v.id} step ${i}: state differs`);
    });
    if (stateJson(vt) !== wantState(v.final)) failures.push(`${v.id}: final state differs`);
  }
  assert.deepEqual(failures, []);
});

test('wallet: capacity preflight and redemption refusals', async () => {
  for (const v of F.wallet.capacity) {
    const z = (x: bigint | undefined): bigint => x ?? 0n;
    const [, e] = await outcome(() => {
      if (v.stage === 'preflight') {
        capacityPreflight({
          lMax: v.maxEncodedTxBytes, lT: v.evidenceBytes, lO: v.otherBytes, K: v.K, a: z(v.a), cObs: z(v.currentSegment), reserve: z(v.returnReserveSegments),
          userGasLimit: z(v.userGasLimit), gasAt: (p) => z(v.gasBase) + z(v.gasPerProof) * p,
        });
      } else capacityExceeded(v.maxEncodedTxBytes, v.evidenceBytes, v.otherBytes, v.K, z(v.proofs), z(v.gasLimit), z(v.userGasLimit));
    });
    assert.equal(norm(expectOf(e)), norm(v.expect), v.id);
    const m = maxProofs(v.maxEncodedTxBytes, v.evidenceBytes, v.otherBytes, v.K);
    assert.equal(m.pMax, v.pMax, v.id);
    assert.equal(m.baseFits, v.baseFits, v.id);
  }
});

test('wallet: companions and state reads', async () => {
  for (const v of F.wallet.companions) {
    const [, e] = await outcome(() => checkCompanion(v.status, Number(v.witnesses)));
    assert.equal(norm(expectOf(e)), norm(v.expect), v.id);
  }
  for (const v of F.wallet.stateReads) {
    const [, e] = await outcome(() => checkStateRead(v.stateReadOnly, v.read, v.verified, v.maxJump));
    assert.equal(norm(expectOf(e)), norm(v.expect), v.id);
  }
});
